<body>
<div class="container">
  <div class="header">
    <div class="month-nav">
      <span class="nav-arrow" id="prev-month">◀</span>
      <div class="month-name" id="month-name"></div>
      <span class="nav-arrow" id="next-month">▶</span>
    </div>
  </div>
  <div class="calendar" id="calendar"></div>
  <div class="time-slots" id="time-slots"></div>
  <div class="doctor">د. محمد علي</div>
  <button class="confirm-btn" id="confirm-btn">تأكيد الحجز</button>
</div>

<script>
  const monthNames = ["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"];
  const dayNames = ["السبت","الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة"];
  let currentMonth = new Date().getMonth();
  let currentYear = new Date().getFullYear();

  const calendarEl = document.getElementById('calendar');
  const monthNameEl = document.getElementById('month-name');
  const prevBtn = document.getElementById('prev-month');
  const nextBtn = document.getElementById('next-month');
  const timeSlotsEl = document.getElementById('time-slots');

  function renderCalendar() {
    calendarEl.innerHTML = '';
    // Add day headers
    dayNames.forEach(day => {
      const header = document.createElement('div');
      header.className = 'day-header';
      header.textContent = day;
      calendarEl.appendChild(header);
    });

    const firstDay = new Date(currentYear, currentMonth, 1);
    const startDay = firstDay.getDay(); // 0 Sunday .. 6 Saturday
    const startOffset = (startDay + 1) % 7; // Saturday is 0

    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const today = new Date();
    const isToday = date => date.toDateString() === today.toDateString();

    let cellIndex = 0;
    // Empty cells before first day
    for (let i = 0; i < startOffset; i++) {
      const empty = document.createElement('div');
      empty.className = 'day-cell';
      empty.style.visibility = 'hidden';
      calendarEl.appendChild(empty);
      cellIndex++;
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const cell = document.createElement('div');
      cell.className = 'day-cell';
      cell.textContent = day;
      const cellDate = new Date(currentYear, currentMonth, day);
      if (isToday(cellDate)) {
        cell.classList.add('today');
      }
      cell.addEventListener('click', () => {
        document.querySelectorAll('.day-cell').forEach(c => c.classList.remove('selected'));
        cell.classList.add('selected');
      });
      calendarEl.appendChild(cell);
      cellIndex++;
    }

    // Fill remaining cells to complete grid (optional)
    const totalCells = 7 * 5; // 5 rows
    while (cellIndex < totalCells) {
      const empty = document.createElement('div');
      empty.className = 'day-cell';
      empty.style.visibility = 'hidden';
      calendarEl.appendChild(empty);
      cellIndex++;
    }

    monthNameEl.textContent = `${monthNames[currentMonth]} ${currentYear}`;
  }

  function renderTimeSlots() {
    timeSlotsEl.innerHTML = '';
    const times = [];
    for (let h = 9; h <= 12; h++) {
      for (let m = 0; m < 60; m += 30) {
        if (h === 12 && m > 0) continue;
        const hour = h.toString().padStart(2,'0');
        const min = m.toString().padStart(2,'0');
        times.push(`${hour}:${min}`);
      }
    }
    times.forEach(time => {
      const slot = document.createElement('div');
      slot.className = 'time-slot';
      slot.textContent = time;
      slot.addEventListener('click', () => {
        document.querySelectorAll('.time-slot').forEach(s => s.classList.remove('selected'));
        slot.classList.add('selected');
      });
      timeSlotsEl.appendChild(slot);
    });
  }

  prevBtn.addEventListener('click', () => {
    currentMonth--;
    if (currentMonth < 0) {
      currentMonth = 11;
      currentYear--;
    }
    renderCalendar();
  });

  nextBtn.addEventListener('click', () => {
    currentMonth++;
    if (currentMonth > 11) {
      currentMonth = 0;
      currentYear++;
    }
    renderCalendar();
  });

  document.getElementById('confirm-btn').addEventListener('click', () => {
    alert('تم تأكيد الحجز');
  });

  renderCalendar();
  renderTimeSlots();
</script>
</body>
</html>
